var a=183;var i=[{id:`cooking-183-01`,theoryId:183,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What gas from yeast fermentation helps bread dough rise?`,ua:`Який газ із дріжджового бродіння допомагає тісту підніматися?`},explanation:{en:`Yeast metabolizes available sugars and releases carbon dioxide that dough traps.`,ua:`Дріжджі засвоюють доступні цукри та виділяють вуглекислий газ, який утримується тістом.`},options:[{id:`a`,text:{en:`Nitrogen from table salt`,ua:`Азот із кухонної солі`}},{id:`b`,text:{en:`Carbon dioxide`,ua:`Вуглекислий газ`}},{id:`c`,text:{en:`Pure oxygen`,ua:`Чистий кисень`}}],answer:{optionIds:[`b`]}},{id:`cooking-183-02`,theoryId:183,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Warmer dough always produces better flavor regardless of fermentation speed.`,ua:`Тепліше тісто завжди дає кращий смак незалежно від швидкості бродіння.`},explanation:{en:`Temperature changes fermentation rate and flavor development; too much heat can damage yeast.`,ua:`Температура змінює швидкість бродіння та формування смаку; надмірне тепло може пошкодити дріжджі.`},answer:{value:!1}},{id:`cooking-183-03`,theoryId:183,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match fermentation observations to likely explanations.`,ua:`Поєднайте ознаки бродіння з імовірними поясненнями.`},explanation:{en:`Fermentation is biological, and both conditions and time matter.`,ua:`Бродіння — біологічний процес, для якого важливі умови та час.`},leftItems:[{id:`l1`,text:{en:`Gas bubbles`,ua:`Газові бульбашки`}},{id:`l2`,text:{en:`Flavor develops over time`,ua:`Смак розвивається з часом`}},{id:`l3`,text:{en:`Very hot mixing liquid`,ua:`Дуже гаряча рідина для замішування`}}],rightItems:[{id:`r1`,text:{en:`Carbon dioxide production and retention`,ua:`Утворення та утримання вуглекислого газу`}},{id:`r3`,text:{en:`May damage yeast viability`,ua:`Може пошкодити життєздатність дріжджів`}},{id:`r2`,text:{en:`Formation of fermentation metabolites`,ua:`Утворення продуктів обміну під час бродіння`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-183-04`,theoryId:183,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Your yeast dough barely rises in a very cold room. Which controlled response makes sense?`,ua:`Дріжджове тісто майже не піднімається в дуже холодному приміщенні. Що доречно?`},explanation:{en:`Low temperatures generally slow yeast fermentation without necessarily stopping it.`,ua:`Низькі температури зазвичай уповільнюють дріжджове бродіння, але не обов’язково зупиняють його.`},options:[{id:`a`,text:{en:`Pour boiling water directly over the dough`,ua:`Залити тісто окропом`}},{id:`b`,text:{en:`Assume the dough has no yeast because it is slow`,ua:`Вважати, що дріжджів немає, лише через повільний підйом`}},{id:`c`,text:{en:`Give more time or move to a moderately warmer environment`,ua:`Дати більше часу або перенести в помірно тепліше місце`}}],answer:{optionIds:[`c`]}},{id:`cooking-183-05`,theoryId:183,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which variables can change yeast dough fermentation?`,ua:`Які чинники можуть змінювати бродіння дріжджового тіста?`},explanation:{en:`Fermentation depends on the microorganism, nutrients and environment.`,ua:`Бродіння залежить від мікроорганізму, поживних речовин та середовища.`},options:[{id:`a`,text:{en:`Amount and activity of yeast`,ua:`Кількість та активність дріжджів`}},{id:`b`,text:{en:`Temperature`,ua:`Температура`}},{id:`c`,text:{en:`Available fermentable sugars`,ua:`Наявні цукри для бродіння`}},{id:`d`,text:{en:`The color of the mixing bowl alone`,ua:`Лише колір миски`}}],answer:{optionIds:[`a`,`b`,`c`]}}];var n={theoryId:183,exercises:i};export{n as default,i as exercises,a as theoryId};